def truncate_string(text: str, max_len: int) -> str:
    if max_len < 0:
        # Python negative index semantics: slice from the end
        truncated = text[max_len:]
        # Append ellipsis only if the truncated result is actually shortened
        if len(truncated) < len(text):
            return truncated + '...'
        return truncated
    if len(text) <= max_len:
        return text
    if max_len < 3:
        # When max_len is less than 3, we can only fit '...' truncated to max_len characters
        return '...'[:max_len]
    # max_len >= 3 and text is too long: keep (max_len - 3) chars then '...'
    return text[:max_len - 3] + '...'
